<script>(function(){const input=document.getElementById('ai-network-logo'),img=document.getElementById('ai-logo-preview'),placeholder=document.getElementById('ai-logo-placeholder');let prev='';input.addEventListener('change',()=>{const file=input.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2097152){alert('Escolha uma imagem PNG, JPG ou WebP de até 2 MB.');input.value='';return}if(prev)URL.revokeObjectURL(prev);prev=URL.createObjectURL(file);img.src=prev;img.hidden=false;if(placeholder)placeholder.hidden=true;img.onload=()=>{if(prev){URL.revokeObjectURL(prev);prev=''}}})})();</script>

<dialog id="ai-delete-dialog" aria-labelledby="ai-delete-title"><form method="post" id="ai-delete-network" autocomplete="off"><input type="hidden" name="_csrf" value="<?=arc_h($csrf)?>"><input type="hidden" name="action" value="network_delete"><input type="hidden" name="network_id" value="<?=(int)$networkId?>"><h3 id="ai-delete-title"><i class="fa fa-lock"></i> Confirmar exclusão da rede</h3><p class="ai-muted" style="line-height:1.6">Esta operação apaga <strong>tudo</strong> desta rede no servidor (computadores, histórico, equipe, perfis, chamados, arquivos e configurações) e <strong>desinstala o gestor</strong> de todas as máquinas, removendo também os dados locais deixados nelas. Máquinas desligadas serão desinstaladas na próxima vez que ficarem online. Não pode ser desfeita.</p><label>Senha de login do gestor<input type="password" name="manager_password" required autocomplete="current-password" minlength="1" autofocus placeholder="Digite sua senha"></label><div class="ai-delete-buttons"><button type="button" class="button" onclick="this.closest('dialog').close()">Cancelar</button><button type="submit" class="button ai-delete-confirm">Confirmar exclusão</button></div></form></dialog>
<script>(function(){const doc=document.getElementById('ai-doc_number');if(!doc)return;let t;doc.addEventListener('input',()=>{clearTimeout(t);const digits=doc.value.replace(/\D/g,'');if(digits.length!==14)return;t=setTimeout(async()=>{try{const r=await fetch(<?=json_encode(arc_workspace_base_url().'pages/painel.php?ajax=cnpj_lookup&cnpj=')?>+encodeURIComponent(digits),{credentials:'same-origin'});if(!r.ok)return;const payload=await r.json();if(!payload.ok||!payload.data)return;const c=payload.data;const values={trade_name:c.nome_fantasia||c.razao_social,company_email:c.email,zip_code:c.cep,state_code:c.uf,city_name:c.municipio,street_name:c.logradouro,street_number:c.numero,address_extra:c.complemento,district_name:c.bairro,registration_status:c.descricao_situacao_cadastral,main_activity:c.cnae_fiscal_descricao,legal_nature:c.natureza_juridica,opening_date:c.data_inicio_atividade};const client=document.querySelector('[name=client_name]');if(client&&c.razao_social)client.value=c.razao_social;const contact=document.querySelector('[name=contact_phone]');if(contact&&c.ddd_telefone_1)contact.value=c.ddd_telefone_1;const address=document.querySelector('[name=address]');if(address)address.value=[c.logradouro,c.numero,c.bairro,c.municipio,c.uf].filter(Boolean).join(', ');for(const [k,v] of Object.entries(values)){const el=document.getElementById('ai-'+k);if(el&&v)el.value=String(v)}}catch(e){}},450)})})();</script>
